Translate("deDE", "silithus", {
	title = "Silithus",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Silithus ist eine Ödnis aus gelbem Sand und zerbrochenem Stein im äußersten Südwesten von {link:kalimdor}Kalimdor{/link}, jenseits des westlichen Randes des {link:un-goro-crater}Un'Goro-Kraters{/link}. Nichts Grünes wächst hier aus freien Stücken. Große Stöcke der {link:qiraji}Silithiden{/link} erheben sich wie geschwollene Türme aus der Wüste, und der Wind trägt ein trockenes Summen, das nie ganz verstummt. Im Südwesten schließt eine Mauer aus dunklem Stein eine uralte Stadt ab. Die {link:night-elves}Nachtelfen{/link} erinnern sich an dieses Land als das Feld ihres bittersten Krieges. Sie sperrten seinen Feind vor langer Zeit ein. Nun ist der Sand wieder in Bewegung.]=],
		},
		{
			title = "Ursprünge",
			text = [=[Keine Chronik verzeichnet, wer diesen Sand als Erster betrat. Die ältesten Geschichten sprechen von den {link:qiraji}Qiraji{/link}, einem Insektenvolk, das im Süden die Festung Ahn'Qiraj errichtete und aus ihren Mauern heraus die Schwärme der Silithiden beherrschte. Vor fast tausend Jahren zogen die Qiraji aus der Wüste, um {link:kalimdor}Kalimdor{/link} zu erobern. Die {link:night-elves}Nachtelfen{/link} stellten sich ihnen hier unter {link:fandral-staghelm}Fandral Staghelm{/link} entgegen und unterlagen. Die ganze Wüste fiel, und die Nachtelfen wurden nach Osten bis an den Rand von {link:tanaris}Tanaris{/link} zurückgedrängt. Erst als sich die Drachenschwärme ihnen anschlossen, wurde der Schwarm aufgehalten. Gemeinsam mauerten sie ihn in seiner eigenen Stadt ein. Dieses Ringen ist als der {link:war-of-the-shifting-sands}Krieg der Sandstürme{/link} in Erinnerung geblieben. Die Ruinen der Außenposten der Nachtelfen liegen noch in der Wüste, und ihre Toten finden keine Ruhe.]=],
		},
		{
			title = "Die Gegenwart",
			text = [=[Der {link:cenarion-circle}Zirkel des Cenarius{/link} ist nach Silithus zurückgekehrt. Seine Druiden und Soldaten halten {link:cenarion-hold}Burg Cenarius{/link} im Herzen der Wüste, und seine Gesandten rufen die {link:alliance}Allianz{/link} ebenso wie die {link:horde}Horde{/link} auf, zu kommen und gegen die {link:qiraji}Silithiden{/link} zu kämpfen, bevor sich der Schwarm ausbreitet. Die drei großen Stöcke, der {link:hive-ashi}Bau des Ashischwarms{/link}, der {link:hive-zora}Bau des Zoraschwarms{/link} und der {link:hive-regal}Bau des Regalschwarms{/link}, werden von Tag zu Tag geschäftiger. In ihrem Inneren stehen seltsame Kristalle voller Glyphen, und die Gelehrten des Zirkels glauben, dass etwas durch sie dem Schwarm Befehle sendet.

Die Silithiden sind nicht die einzige Bedrohung. Der {link:twilight-s-hammer}Schattenhammer{/link} hat überall im Westen der Wüste Lager errichtet, in denen seine Kultisten Windsteine aufstellen und die Edlen eines elementaren Rates herbeirufen. In {link:bronzebeard-encampment}Bronzebeards Lager{/link} im Süden durchsuchen {link:dwarves}Zwerge{/link} der {link:explorers-league}Forscherliga{/link} die Stöcke nach verlorenen Relikten; ihr Anführer, {link:brann-bronzebeard}Brann Bronzebeard{/link}, ist wieder einmal verschollen. Der Kommandant von Burg Cenarius hat seine Gemahlin an die Stöcke verloren. Die Zwerge schwören, dass sie Drachen am Himmel gesehen haben, wo seit tausend Jahren kein Drache mehr geflogen ist. Jenseits des Skarabäuswalls warten die Qiraji.]=],
		},
		{
			title = "Bewohner",
			text = [=[• {b}Der {link:cenarion-circle}Zirkel des Cenarius{/link}.{/b} Druiden, Gelehrte und Soldaten der {link:night-elves}Nachtelfen{/link} und der {link:tauren}Tauren{/link}, die {link:cenarion-hold}Burg Cenarius{/link} halten und in der {link:valor-s-rest}Heldenwacht{/link} Wache stehen.
• {b}Die {link:qiraji}Silithiden{/link}.{/b} Stecher, Drohnen, Häscher, Tunnelgräber und Wespen der drei Stöcke, und die Oberanführer, die über sie herrschen.
• {b}Die Qiraji.{/b} Die Herren des Schwarms, hinter dem {link:the-scarab-wall}Skarabäuswall{/link} in der Stadt Ahn'Qiraj eingeschlossen.
• {b}Der {link:twilight-s-hammer}Schattenhammer{/link}.{/b} Kultisten, Geolords, Hüter und Propheten in {link:camping}Lagern{/link} überall in der westlichen Wüste und in einer Höhle namens {link:twilight-s-run}Kavernen der Twilight{/link}.
• {b}Die Elementare.{/b} Wüstenrumpler, Staubstürmer und Zyklonkrieger, und die Templer des {link:abyssal-council}Abyssal Council{/link}.
• {b}Die {link:dwarves}Zwerge{/link}.{/b} Forscher der {link:explorers-league}Forscherliga{/link} in {link:bronzebeard-encampment}Bronzebeards Lager{/link}.
• {b}Die Tiere.{/b} Steinpeitscher-Skorpide, Sandhuscher, Felspirscher und große Baggerwürmer, die Jagd auf die Karawanen machen.
• {b}Die Toten.{/b} Die gequälten Geister der Druiden und {link:sentinels}Schildwachen{/link}, die im {link:southwind-village}Südwindposten{/link} fielen.]=],
		},
		{
			title = "Geschichte",
			text = [=[• {b}Das Zeitalter der Stöcke.{/b} Lange bevor die {link:night-elves}Nachtelfen{/link} kamen, errichteten die {link:qiraji}Qiraji{/link} Ahn'Qiraj und züchteten ihre Schwärme unter dem Sand.
• {b}Der {link:war-of-the-shifting-sands}Krieg der Sandstürme{/link}.{/b} Die Qiraji fielen in {link:kalimdor}Kalimdor{/link} ein. Der {link:southwind-village}Südwindposten{/link} fiel und mit ihm {link:valstann-staghelm}Valstann Staghelm{/link}. Die Nachtelfen wurden bis nach {link:tanaris}Tanaris{/link} zurückgedrängt, bis die Drachenschwärme in den Kampf eingriffen und halfen, Ahn'Qiraj hinter einer großen Barriere zu versiegeln.
• {b}Das lange Schweigen.{/b} Jahrhundertelang hielt der Wall. Die Wüste wurde den Silithiden und den Toten überlassen.
• {b}Die Gegenwart.{/b} Der {link:cenarion-circle}Zirkel des Cenarius{/link} ist zurückgekehrt, der {link:twilight-s-hammer}Schattenhammer{/link} ist mit eigenen Absichten gekommen, und die Stöcke regen sich.]=],
		},
		{
			title = "Überlieferungen des Sandes",
			text = [=[• Die Wirtin von {link:cenarion-hold}Burg Cenarius{/link} lernte, Sandwurm zu kochen, aus einem Kochbuch, das in einem Lager des Schattenhammers gefunden wurde. Sie gibt zu, dass die Klöße besser sind, als sie es von solchen Leuten erwartet hätte.
• Die {link:dwarves}Zwerge{/link} in {link:bronzebeard-encampment}Bronzebeards Lager{/link} behaupten, dass sie zusammen, den Affen mitgezählt, achtunddreißig Sprachen beherrschen. Keiner von ihnen konnte die Sprache benennen, in der {link:natalia-mar-alith}Natalia Mar'alith{/link} sang.
• Ein {link:the-night-watch}Wächter{/link} in der östlichen Wüste sagt, er sei hundertmal erschlagen worden und erwache immer wieder am selben Ort.
• Der {link:twilight-s-hammer}Schattenhammer{/link} verbreitet unter seinen Gläubigen ein monatliches Mitteilungsblatt, in Geheimschrift verfasst. Auch seine Abtrünnigen lesen es.]=],
		},
	},
})

Translate("deDE", "cenarion-hold", {
	title = "Burg Cenarius",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Burg Cenarius ist die Festung des {link:cenarion-circle}Zirkels des Cenarius{/link} im Herzen von {link:silithus}Silithus{/link}. Sie wurde errichtet, um die {link:qiraji}Silithiden{/link} dort zu treffen, wo sie am stärksten sind. Ihre Soldaten unterstehen {link:commander-mar-alith}Kommandant Mar'alith{/link}, {link:windcaller-proudhorn}Windrufer Proudhorn{/link} begrüßt jeden neuen Rekruten, und Hauptmann {link:vish-kozus}Vish Kozus{/link} überwacht die Wüste von der Spitze des Wachturms aus. Hier landen sowohl Hippogryphen als auch Windreiter, denn die Burg heißt die {link:alliance}Allianz{/link} und die {link:horde}Horde{/link} gleichermaßen willkommen. Die Burg lebt von den Vorräten, die ihre Karawanen durch den Sand schleppen, und die Würmer der Wüste machen Jagd auf sie.]=],
		},
	},
})

Translate("deDE", "the-scarab-wall", {
	title = "Der Skarabäuswall",
	aliases = { "Skarabäuswall", "Die Skarabäushöhe" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Im äußersten Südwesten von {link:silithus}Silithus{/link} zieht sich eine Mauer aus dunklem Stein quer durch die Wüste. Hinter ihr liegt Ahn'Qiraj, die Stadt der {link:qiraji}Qiraji{/link}. Die Barriere wurde am Ende des {link:war-of-the-shifting-sands}Krieges der Sandstürme{/link} von den {link:night-elves}Nachtelfen{/link} und den Drachenschwärmen gemeinsam errichtet, und sie schöpft aus der Macht beider. Sie wurde als Gefängnis geschaffen, und seit fast tausend Jahren hat sie gehalten. Nahe der Barriere liegt ein einzelner Kristall, die Kristallene Träne. Wer in sie blickt, fühlt das ganze Leid jenes Krieges auf einmal. Die großen Tore des Walls sind verschlossen.]=],
		},
	},
})

Translate("deDE", "southwind-village", {
	title = "Südwindposten",
	aliases = { "Südwind" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Südwindposten war einst ein Außenposten der {link:night-elves}Nachtelfen{/link} in {link:silithus}Silithus{/link}. Im {link:war-of-the-shifting-sands}Krieg der Sandstürme{/link} zog {link:valstann-staghelm}Valstann Staghelm{/link} aus, um ihn zu verteidigen, und er fiel an die Heere von Ahn'Qiraj. Seine Ruinen stehen in der östlichen Wüste. Die gequälten Geister der Druiden und {link:sentinels}Schildwachen{/link}, die dort starben, wandern noch zwischen den zerbrochenen Mauern umher, und ein Stock der {link:qiraji}Silithiden{/link} hat seinen Turm verschlungen, um den rastlos Wespen kreisen. Eine schweigende geisterhafte Frau verweilt in den Ruinen und handelt mit Lederverarbeitungsmustern. Der Zirkel wusste, dass hier seit alten Tagen ein seltenes Reliquiar der Reinheit verborgen lag.]=],
		},
	},
})

Translate("deDE", "valor-s-rest", {
	title = "Heldenwacht",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Heldenwacht ist ein Friedhof im Nordosten von {link:silithus}Silithus{/link}, die letzte Ruhestätte derer, die in der Ödnis fallen. Sie liegt fern der Stöcke und der Lager. {link:layo-starstrike}Layo Starstrike{/link}, ein Agent des {link:cenarion-circle}Zirkels des Cenarius{/link}, empfängt Reisende an den Gräbern. Bei ihm warten ein weiterer Diener des Zirkels und ein Händler für Lederwaren. Von hier führt der Weg zu den Ruinen des Südwindpostens nach Südwesten.]=],
		},
	},
})

Translate("deDE", "hive-ashi", {
	title = "Bau des Ashischwarms",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Bau des Ashischwarms ist der nördliche Stock von {link:silithus}Silithus{/link}, der {link:cenarion-hold}Burg Cenarius{/link} am nächsten. Stecher, Arbeiter, Drohnen, Schwärmer und Sandpirscher strömen aus seinen großen Hügeln. Wie die anderen Stöcke birgt er einen Glyphenkristall, der mit seltsamen Zeichen bedeckt ist. Die Gelehrten des Zirkels glauben, dass die {link:qiraji}Qiraji{/link} ihre Befehle durch solche Kristalle an den Schwarm senden. Der Oberanführer des Ashischwarms, Aluntir, ist einer der drei Stockherren, die in den Glyphen bei einem Treffen mit einem Abgesandten der Qiraji gezeigt werden.]=],
		},
	},
})

Translate("deDE", "hive-zora", {
	title = "Bau des Zoraschwarms",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Bau des Zoraschwarms ist der westliche Stock von {link:silithus}Silithus{/link}. Seine Wegwächter, Tunnelgräber, Wespen, Häscher und Stockschwestern bewachen einen großen Hügel, der sich aus der westlichen Wüste erhebt. Wie seine Geschwister birgt er einen Glyphenkristall. Arakis, der Oberanführer des Zoraschwarms, ist einer der drei Stockherren, die der Zirkel ins Freie zu locken hofft.]=],
		},
	},
})

Translate("deDE", "hive-regal", {
	title = "Bau des Regalschwarms",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Bau des Regalschwarms ist der südliche Stock von {link:silithus}Silithus{/link}. Seine Wühler, Lauerer, Feuerspucker und Sklaventreiber gehorchen dem Oberanführer Xil'xix. Die {link:dwarves}Zwerge{/link} der {link:explorers-league}Forscherliga{/link} drangen auf der Suche nach Relikten in ihn ein und fanden einen Glyphenkristall. Die Priesterin der {link:night-elves}Nachtelfen{/link} {link:natalia-mar-alith}Natalia Mar'alith{/link} drückte ihre Wange daran und fiel in Trance. Wochen später floh sie zurück in den Stock, und die {link:qiraji}Silithiden{/link} wichen zur Seite, um sie durchzulassen. Sie ist nicht wieder herausgekommen.]=],
		},
	},
})

Translate("deDE", "bronzebeard-encampment", {
	title = "Bronzebeards Lager",
	aliases = { "Bronzebeard-Lager", "Lager von Bronzebeard" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Bronzebeards Lager ist das Lager der {link:explorers-league}Forscherliga{/link} im äußersten Süden von {link:silithus}Silithus{/link}. {link:brann-bronzebeard}Brann Bronzebeard{/link} führte seine Forscher hierher, um die Stöcke nach verlorenen Artefakten zu durchsuchen. Nun ist Brann fort, und nur {link:rutgar-glyphshaper}Rutgar Glyphshaper{/link}, {link:frankal-stonebridge}Frankal Stonebridge{/link} und Branns Affe {link:glibb}Glibb{/link} halten das Lager. Sie haben {link:ironforge}Ironforge{/link} um ein Heer gebeten, das ihnen hilft, in die Stöcke einzudringen. Ironforge hat nicht geantwortet. Hinter dem Lager erheben sich die südlichen Berge, in denen ein großer Skorpid jagt.]=],
		},
	},
})

Translate("deDE", "the-crystal-vale", {
	title = "Das Kristalltal",
	aliases = { "Kristalltal", "Verwüsteter Twilight-Stützpunkt" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Das Kristalltal liegt in der nordwestlichen Ecke von {link:silithus}Silithus{/link}. Elementare der Luft und der Erde streifen frei umher. Einst stand hier ein Lager des {link:twilight-s-hammer}Schattenhammers{/link}. Nun markieren nur verstreutes Holz und Segeltuch die Stelle, mit Bruchstücken einer Tontafel, die im Sand vergraben sind. Die Tafel erzählt von einem nördlichen Lager, dem ersten, das seinen Windstein vollendete. Ein Mitteilungsblatt des Kults erzählt von einem nördlichen Lager, das von einem der Fürsten zerstört wurde, die seine Mitglieder gerufen hatten. Am Rand des verwüsteten Feldes wartet ein Hochlord und spricht vom Prinzen der Lüfte.]=],
		},
	},
})

Translate("deDE", "twilight-base-camp", {
	title = "Basislager der Twilight",
	aliases = { "Twilight-Posten", "Twilight-Außenposten" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der {link:twilight-s-hammer}Schattenhammer{/link} hält drei Lager in der westlichen Hälfte von {link:silithus}Silithus{/link}: eines westlich von {link:cenarion-hold}Burg Cenarius{/link}, eines weiter westlich und eines im Südwesten nahe dem {link:the-scarab-wall}Skarabäuswall{/link}. In jedem haben die Kultisten Windsteine errichtet, kleinere und größere, durch die sie mit den elementaren Edlen des {link:abyssal-council}Abyssal Council{/link} sprechen. Hüter des Schattenhammers bewahren die Kapitel des geheimen Lexikons des Kults, Geolords leiten die Rituale, und Propheten predigen von den Tagen des Endes. Der Zirkel vermutet, dass die Lager mit den pulsierenden roten Kristallen überall in der Wüste verbunden sind.]=],
		},
	},
})

Translate("deDE", "twilight-s-run", {
	title = "Kavernen der Twilight",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Kavernen der Twilight sind eine Höhle, die sich in die nordöstliche Ecke von {link:silithus}Silithus{/link} schmiegt. Sie sind eine Hochburg des {link:twilight-s-hammer}Schattenhammers{/link} und der Unterschlupf von {link:vyral-the-vile}Vyral{/link} dem Niederträchtigen, dem örtlichen Anführer des Kults. Oberanführer und Flammenhäscher des Kults bewachen ihre Tunnel. Der Zirkel entdeckte sie erst nach seinen ersten Schlägen gegen die Geolords der westlichen Lager.]=],
		},
	},
})

Translate("deDE", "ortell-s-hideout", {
	title = "Ortells Unterschlupf",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[In den Bergen südlich des Südwindpostens verbirgt sich ein Mann vor seinen einstigen Brüdern. {link:hermit-ortell}Ortell{/link} war einst ein Mitglied des {link:twilight-s-hammer}Schattenhammers{/link}. Er lief davon, und der Kult jagt ihn seither. Er lebt dort als Einsiedler und begegnet jedem Fremden mit Misstrauen. Wer ihm jedoch Kunde gegen den Kult bringt, mag in ihm einen nützlichen Freund finden.]=],
		},
	},
})

Translate("deDE", "bones-of-grakkarond", {
	title = "Knochen von Grakkarond",
	aliases = { "Grakkarond" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Südlich von {link:cenarion-hold}Burg Cenarius{/link} liegen die Knochen eines großen Drachen gebleicht im Sand. Die Glyphen der Stöcke zeigen einen Ort wie diesen: einen Abgesandten der {link:qiraji}Qiraji{/link}, der sich bei den Knochen eines großen Drachen mit drei Herren der Silithiden trifft. {link:geologist-larksbane}Geologin Larksbane{/link} glaubt, dass die richtigen Glyphen, hier in den Sand gezeichnet, die Stockherren und ihren Abgesandten aus ihrem Versteck rufen werden. Keine Aufzeichnung verrät, wer Grakkarond war oder wie der Drache in dieser Wüste zu Tode kam.]=],
		},
	},
})

Translate("deDE", "qiraji", {
	title = "Qiraji",
	aliases = { "Silithiden" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Qiraji sind ein uraltes, denkendes Insektenvolk der südlichen Wüste. Sie erbauten die Festung Ahn'Qiraj in {link:silithus}Silithus{/link}, und von dort aus befehligen sie die Silithiden, die schwärmenden Insekten, die die Stöcke des Landes füllen. Die Silithiden sind unzählbar, und jede Stunde schlüpfen mehr. Die Qiraji sind ihre Herren: keine Tiere, sondern Ränkeschmiede, mit eigenen Generälen und Königen.]=],
		},
		{
			title = "Ursprünge",
			text = [=[Die ältesten Geschichten Kalimdors erzählen von den Aqir, einem Insektenreich, das mit den uralten Trollen Krieg führte. Als die Aqir zurückgedrängt wurden, zog sich ein Teil ihres Volkes nach Süden zurück, in das Land, das {link:silithus}Silithus{/link} werden sollte, und wurde dort zu den Qiraji. Das Buch der {link:night-elves}Nachtelfen{/link} über den Krieg berichtet, dass die Qiraji einst um die Herrschaft über weite Teile Kalimdors rangen.]=],
		},
		{
			title = "Der Schwarm",
			text = [=[Die Silithiden handeln nicht allein. In jedem der drei Stöcke steht ein Glyphenkristall, und die Gelehrten des Zirkels des {link:cenarius}Cenarius{/link} glauben, dass die Qiraji und andere, noch unbekannte Mächte durch sie ihre Botschaften an den Schwarm senden. Jeder Stock hat seinen eigenen Oberanführer, und die Oberanführer versammeln sich, wenn die Glyphen sie rufen.]=],
		},
		{
			title = "Die Macht im Tempel",
			text = [=[Während des Krieges der Sandstürme spürte der Drache Arygos eine seltsame, dumpfe Magie im großen Tempel von Ahn'Qiraj. Keiner der Drachen konnte ihre Quelle erreichen. Sie gelangten zu dem Glauben, dass etwas dort nicht nur die Silithiden, sondern auch die Qiraji selbst lenkte. Eine Nachtelfe, die einen Glyphenkristall berührte, gab ihm tausend Jahre später einen Namen: {red:c-thun}C'Thun{/red}.]=],
		},
	},
})

Translate("deDE", "war-of-the-shifting-sands", {
	title = "Krieg der Sandstürme",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Krieg der Sandstürme wurde vor fast tausend Jahren zwischen den {link:night-elves}Nachtelfen{/link} und den {link:qiraji}Qiraji{/link} von Ahn'Qiraj geführt. Er endete nicht mit einem Sieg, sondern mit einem Gefängnis.]=],
		},
		{
			title = "Der Einfall",
			text = [=[Aus Ahn'Qiraj zogen die {link:qiraji}Qiraji{/link} unter General Rajaxx aus, mit endlosen Schwärmen von Silithiden hinter sich. {link:fandral-staghelm}Fandral Staghelm{/link} sammelte die Heere der {link:night-elves}Nachtelfen{/link} gegen sie, und sein Sohn {link:valstann-staghelm}Valstann{/link} kämpfte an seiner Seite. Das Buch der Nachtelfen über den Krieg berichtet, dass Fandral Valstann befahl, den {link:southwind-village}Südwindposten{/link} zu halten. Ein Tagebuch, das in seinen Ruinen gefunden wurde, erzählt mehr: Die Zwillingsimperatoren von Ahn'Qiraj stellten dort eine Falle, Valstann wurde gefangen genommen, und Rajaxx tötete ihn vor den Augen des Heeres seines Vaters. Der Krieg dauerte Monate. Schließlich war ganz {link:silithus}Silithus{/link} verloren, und das geschlagene Heer der Nachtelfen wurde durch {link:un-goro-crater}Un'Goro{/link} bis nach {link:tanaris}Tanaris{/link} zurückgetrieben.]=],
		},
		{
			title = "Die Drachen",
			text = [=[Dort ging {link:fandral-staghelm}Fandral{/link}, gedemütigt, zu Anachronos, dem Sohn von {red:nozdormu}Nozdormu{/red}, und flehte um die Hilfe der bronzenen Drachen. Anachronos lehnte ab, bis die {link:qiraji}Qiraji{/link} es wagten, die Höhlen der Zeit anzugreifen. Selbst der bronzene Schwarm konnte den Schwarm der Insekten nicht zurückhalten, und so rief Anachronos die Kinder der anderen Aspekte. Merithra kam für den Schwarm von {red:ysera}Ysera{/red}, Caelestrasz für den von {link:alexstrasza}Alexstrasza{/link} und Arygos für den von {red:malygos}Malygos{/red}. Hoch über Ahn'Qiraj erkannten sie, dass keine noch so große Gewalt den Krieg beenden konnte. Sie beschlossen, den Feind in seiner eigenen Stadt einzuschließen.]=],
		},
		{
			title = "Der Wall und das Zepter",
			text = [=[Aus der Macht der {link:night-elves}Nachtelfen{/link} und der Drachen schöpfend, errichteten sie eine große Barriere um Ahn'Qiraj. Merithra, Caelestrasz und Arygos warfen sich den {link:qiraji}Qiraji{/link} entgegen, um Zeit zu gewinnen, während Anachronos und {link:fandral-staghelm}Fandral{/link} das Tor versiegelten. Als es vollbracht war, gab Anachronos Fandral ein Zepter, das die Barriere wieder öffnen konnte. Der Erzdruide, in Trauer um seinen Sohn, schleuderte es gegen die Barriere und zerschmetterte es. Anachronos sammelte die Stücke und gab sie in die Obhut der vier großen Drachenschwärme, damit niemand es leicht wieder zusammenfügen konnte.]=],
		},
	},
})

Translate("deDE", "abyssal-council", {
	title = "Abyssal Council",
	aliases = { "Abyssal High Council" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Abyssal Council ist eine Rangordnung elementarer Edler, denen der {link:twilight-s-hammer}Schattenhammer{/link} in {link:silithus}Silithus{/link} dient. Der Kult nennt sie seine Meister und spricht mit ihnen durch die Windsteine seiner Lager. Der {link:cenarion-circle}Zirkel des Cenarius{/link} hat erfahren, dass {link:shadow-council}der Rat{/link} den Kult durch diese Steine lenkt und dass die Kultisten ihre Befehle von ihm empfangen.]=],
		},
		{
			title = "Die Ränge",
			text = [=[Zuunterst stehen die Templer: der Crimson Templar, der Azure Templar, der Hoary Templar und der Earthen Templar. Über ihnen stehen vier Herzöge: der Duke of Cynders, der Duke of Fathoms, der Duke of Zephyrs und der Duke of Shards. An der Spitze sitzt der Hohe Rat aus vier Fürsten: Prinz Skaldrenox, Hochmarschall Whirlaxis, Baron Kazum und Lord Skwol.]=],
		},
		{
			title = "Die Windsteine",
			text = [=[Die eigenen Regeln des Kults sind streng. Eingeweihte dürfen einen Templer rufen, doch sie müssen die rechte Gewandung tragen, sonst erwachen die Abwehrkräfte des Steins. Nur wer ein Standesmedaillon trägt, darf mit einem Herzog sprechen. Nur die Schattenfürsten dürfen den Hohen Rat anrufen, und jeder Außenstehende, der es versucht, soll zu Asche verbrannt werden. Eine Handwerkerin des Zirkels hat gelernt, die Medaillons zu schmieden. Mit einem solchen, und in der eigenen Gewandung des Kults, kann ein kühner Kämpfer einen Edlen des Rates aus dem Stein rufen und ihn niederstrecken.]=],
		},
	},
})

Translate("deDE", "commander-mar-alith", {
	title = "Kommandant Mar'alith",
	subtitle = "Kommandant von Burg Cenarius",
	found = "Burg Cenarius",
	hint = "Sprecht mit dem Kommandanten, der Burg Cenarius hält.",
	allegiance = "Zirkel des Cenarius · Burg Cenarius",
	aliases = { "Mar'alith" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Kommandant Mar'alith führt die Streitkräfte des {link:cenarion-circle}Zirkels des Cenarius{/link} in {link:cenarion-hold}Burg Cenarius{/link}. Seine Aufgabe ist es, das Herz von {link:silithus}Silithus{/link} gegen die {link:qiraji}Silithiden{/link} zu halten und den Griff des {link:twilight-s-hammer}Schattenhammers{/link} um die Wüste zu brechen. Er tut seine Pflicht, doch seine Gedanken sind anderswo. Seine geliebte {link:natalia-mar-alith}Natalia{/link} ist verschwunden, und die Pflicht bindet ihn an seinen Posten. Er kann nicht verstehen, warum dies gerade jetzt über ihn gekommen ist, da noch so viel Arbeit zu tun ist.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Mar'alith ist der Erste, der den Preis der Rückkehr des Zirkels nach {link:silithus}Silithus{/link} zu spüren bekommt. Dieselben Stöcke, gegen die er gesandt wurde, haben ihm die Frau genommen, die er liebt. Durch seinen Verlust erfährt der Zirkel den Namen der Macht hinter dem Schwarm.]=],
		},
		{
			title = "Taten",
			text = [=[• Er befehligt {link:cenarion-hold}Burg Cenarius{/link} und ihre Soldaten.
• Er empfängt die entschlüsselten Geheimnisse des Schattenhammers.
• Er schickt Suchende zu {link:bronzebeard-encampment}Bronzebeards Lager{/link} und dann in den {link:hive-regal}Bau des Regalschwarms{/link}, um Natalias Schicksal zu erfahren.]=],
		},
		{
			title = "Nicht überliefert",
			text = [=[Keine Aufzeichnung berichtet, wie Mar'alith und {link:natalia-mar-alith}Natalia{/link} zueinanderfanden oder wie er zum Befehlshaber der Burg wurde.]=],
		},
	},
	chapters = {
		{
			title = "Eine schreckliche Absicht",
			hint = "Bringt dem Kommandanten die Geheimnisse des Schattenhammers.",
			text = [=[Eine Tafel aus einem zerstörten Lager des Kults gelangte zu ihm, entschlüsselt von einem Abtrünnigen des Kults. Sie erzählte von Pilgern, die sich in {link:silithus}Silithus{/link} versammelten, um einen Windstein zu errichten und einen Baron unter den Fürsten der {link:elements}Elemente{/link} heraufzubeschwören. Für Mar'alith war sie ein Schatz. Endlich wusste er, warum der {link:twilight-s-hammer}Schattenhammer{/link} in die Wüste gekommen war, und er konnte seinen Kampf gegen ihn planen.]=],
		},
		{
			title = "Liebste Natalia",
			hint = [=[Erfahrt von den Zwergen, was aus der Geliebten des Kommandanten wurde.]=],
			text = [=[In den Wochen vor ihrem Verschwinden hatte {link:natalia-mar-alith}Natalia{/link} mit sich selbst gesprochen, wenn sie glaubte, niemand sei in der Nähe. Sie beharrte darauf, dass alles gut sei und ihre Forschung weitergehen müsse. Zuletzt wurde sie gesehen, wie sie nach Süden zum Lager der {link:dwarves}Zwerge{/link} ging. Was die Zwerge von ihr erzählten, ließ den Kommandanten den Kopf senken. Ob lebendig oder tot, sagte er, sie musste gefunden werden.]=],
		},
		{
			title = "In den Schlund des Wahnsinns",
			hint = [=[Betretet den Bau des Regalschwarms und erfahrt das Schicksal von Natalia Mar'alith.]=],
			text = [=[Er sandte seinen Suchenden mit einem harten Befehl in den {link:hive-regal}Bau des Regalschwarms{/link}: Wenn sie wirklich dem Wahnsinn verfallen war, sollte er tun, was getan werden musste. Dann wandte er sich ab. Als der Suchende zurückkehrte, hörte der Kommandant, was aus {link:natalia-mar-alith}Natalia{/link} geworden war, und einen Namen, den er nie gekannt hatte. Die Hand an die Brust gepresst, fragte er, was C'Thun sein könne und wie es aus ihr ein Ungeheuer habe machen können.]=],
		},
	},
	mentions = {
		{ text = "Eine schreckliche Absicht" },
		{ text = "Liebste {link:natalia-mar-alith}Natalia{/link}" },
		{ text = "In den Schlund des Wahnsinns" },
	},
	bonds = {
		{ id = "natalia-mar-alith", name = "Natalia Mar'alith", note = "seine Geliebte, im Stock verloren" },
		{ id = "vish-kozus", name = "Vish Kozus", note = "sein Hauptmann der Wache" },
		{ id = "windcaller-proudhorn", name = "Windrufer Proudhorn", note = "begrüßt die Rekruten in seiner Burg" },
		{ id = "hermit-ortell", name = "Einsiedler Ortell", note = "sandte ihm die Geheimnisse des Kults" },
		{ id = "rutgar-glyphshaper", name = "Rutgar Glyphshaper", note = "erzählte von Natalias Fall" },
	},
})

Translate("deDE", "natalia-mar-alith", {
	title = "Natalia Mar'alith",
	subtitle = "Hohepriesterin von C'Thun",
	found = "Die Tiefen des Baus des Regalschwarms",
	hint = [=[Sucht die verlorene Geliebte des Kommandanten in den Tiefen des Baus des Regalschwarms.]=],
	allegiance = "Einst der Zirkel des Cenarius · C'Thun",
	aliases = { "Herrin Natalia Mar'alith", "Natalia" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Natalia Mar'alith war eine Priesterin der {link:night-elves}Nachtelfen{/link} aus {link:cenarion-hold}Burg Cenarius{/link} und die Geliebte ihres Kommandanten. Sie war die Erste unter den Nachtelfen der Burg, die sich den Zwergen bei ihrer Durchsuchung der Stöcke anschloss. Im {link:hive-regal}Bau des Regalschwarms{/link} berührte sie einen Glyphenkristall, und etwas berührte sie zurück. Nun trägt sie den Titel einer Hohepriesterin von {red:c-thun}C'Thun{/red}.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Natalias Fall zeigt, dass die in Ahn'Qiraj eingeschlossene Macht die Lebenden noch erreichen kann. Durch sie hörte der {link:cenarion-circle}Zirkel des Cenarius{/link} zum ersten Mal den Namen C'Thun.]=],
		},
		{
			title = "Taten",
			text = [=[• Sie schloss sich der {link:explorers-league}Forscherliga{/link} bei ihren Vorstößen in die Stöcke an.
• Sie fiel am Glyphenkristall des Baus des Regalschwarms in Trance und erwachte wieder unter der Pflege der Druiden des Zirkels.
• Sie wandte sich im Lager gegen die {link:dwarves}Zwerge{/link} und floh durch die Reihen der {link:qiraji}Silithiden{/link} in den {link:hive-regal}Bau des Regalschwarms{/link}.]=],
		},
		{
			title = "Nicht überliefert",
			text = [=[Nichts ist über Natalias Leben vor {link:silithus}Silithus{/link} geschrieben, noch über die Forschung, die sie nicht aufgeben wollte.]=],
		},
	},
	chapters = {
		{
			title = "Der Kristall im Stock",
			hint = "Hört die Geschichte der Zwerge über die Priesterin.",
			text = [=[Als die {link:dwarves}Zwerge{/link} Natalia aus dem {link:hive-regal}Bau des Regalschwarms{/link} trugen, weckten die Druiden des Zirkels sie, und einige Wochen lang schien alles gut. Dann kam sie zum Lager der Zwerge zurück und verlangte, dass sie sofort in den Stock zurückkehrten. {link:brann-bronzebeard}Brann Bronzebeard{/link} weigerte sich, ohne ein Heer zu gehen. Natalia begann in einer Sprache zu reden, die keiner von ihnen kannte, zu jemandem, den keiner von ihnen sehen konnte. Dann griff sie an. Ihre Augen glühten, und sie trieb schattenhafte Worte in ihren Geist. Branns Affe rettete sie. Sie floh in den Stock, und die {link:qiraji}Silithiden{/link} ließen sie passieren.]=],
		},
		{
			title = "Der Schlund des Wahnsinns",
			hint = "Stellt Euch dem, was im Bau des Regalschwarms wartet.",
			text = [=[Der Suchende ihres Geliebten fand sie tief im {link:hive-regal}Bau des Regalschwarms{/link}. Sie war nicht mehr die Frau, die {link:cenarion-hold}Burg Cenarius{/link} verlassen hatte. Sie diente nun einem Alten Gott, als seine Hohepriesterin.]=],
		},
	},
	mentions = {
		{ text = "Liebste Natalia" },
		{ text = "In den Schlund des Wahnsinns" },
		{
			text = [=[{link:brann-bronzebeard}Brann{/link} Bronzebeards verlorener Brief, der vor ihr warnt]=],
		},
	},
	bonds = {
		{ id = "commander-mar-alith", name = "Kommandant Mar'alith", note = "ihr Geliebter" },
		{ id = "frankal-stonebridge", name = "Frankal Stonebridge", note = "überlebte ihren Angriff" },
		{ id = "rutgar-glyphshaper", name = "Rutgar Glyphshaper", note = "trug sie aus dem Stock" },
		{ id = "glibb", name = "Glibb", note = "vertrieb sie" },
	},
})

Translate("deDE", "valstann-staghelm", {
	title = "Valstann Staghelm",
	subtitle = "Sohn des Erzdruiden",
	found = "Fiel im Südwindposten, im Krieg der Sandstürme",
	hint = "Lest vom Krieg, den die Nachtelfen in der Wüste führten.",
	allegiance = "Nachtelfen · das Heer von Fandral Staghelm",
	aliases = { "Valstann" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Valstann Staghelm war der Sohn von {link:fandral-staghelm}Fandral Staghelm{/link} und seine rechte Hand. Er kämpfte an der Seite seines Vaters im {link:war-of-the-shifting-sands}Krieg der Sandstürme{/link}, als die {link:night-elves}Nachtelfen{/link} versuchten, die {link:qiraji}Qiraji{/link} in {link:silithus}Silithus{/link} aufzuhalten. Er wurde ausgesandt, um den {link:southwind-village}Südwindposten{/link} zu verteidigen. Der Posten fiel, und Valstann starb.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Valstanns Tod ist die Wunde im Mittelpunkt des Lebens des Erzdruiden. Das eigene Buch der {link:night-elves}Nachtelfen{/link} über den Krieg hält fest, dass die Ereignisse in {link:silithus}Silithus{/link} Fandrals verbittertes Wesen in späteren Jahren stark prägten. Es war ein trauernder Vater, der das Zepter an der Barriere von Ahn'Qiraj zerschmetterte.]=],
		},
		{
			title = "Taten",
			text = [=[• Er kämpfte mit seinem Vater gegen die Schwärme von Ahn'Qiraj.
• Er zog zur Verteidigung des Südwindpostens aus und wurde gefangen genommen, als dieser fiel.]=],
		},
		{ title = "Nicht überliefert", text = "Keine Chronik verzeichnet Valstanns Alter oder seine Mutter." },
	},
	chapters = {
		{
			title = "Der Fall von Südwind",
			hint = "Wandelt durch die Ruinen, in denen Valstann fiel.",
			text = [=[{link:southwind-village}Südwind{/link} war ein Außenposten der {link:night-elves}Nachtelfen{/link} in der östlichen Wüste. Das Buch über den Krieg berichtet, dass {link:fandral-staghelm}Fandral{/link} seinem Sohn befahl, ihn zu verteidigen, eine Entscheidung, die er bereuen sollte. Ein in den Ruinen gefundenes Tagebuch sagt, dass Valstann, begierig, seinem Vater zu gefallen, darum bat, gehen zu dürfen. Die Zwillingsimperatoren von Ahn'Qiraj hatten ihre Heere unter dem Sand verborgen, und die Falle wurde nicht erkannt. Der Posten wurde zerstört. General Rajaxx brachte Valstann an die Front und tötete ihn vor den Augen seines Vaters. Die Ruinen stehen noch, und die Geister von Druiden und {link:sentinels}Schildwachen{/link} wandeln durch sie.]=],
		},
	},
	bonds = {
		{ id = "fandral-staghelm", name = "Fandral Staghelm", note = "sein Vater" },
	},
})

Translate("deDE", "baristolth-of-the-shifting-sands", {
	title = "Baristolth der Sandstürme",
	subtitle = "Wächter der Bronzenen",
	found = "Burg Cenarius",
	hint = [=[Sprecht mit dem Wächter in Burg Cenarius, der sich an den alten Krieg erinnert.]=],
	allegiance = "Der bronzene Drachenschwarm · Burg Cenarius",
	aliases = { "Baristolth" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Baristolth der Sandstürme steht in {link:cenarion-hold}Burg Cenarius{/link} und blickt zu den Stöcken hinüber. Vor tausend Jahren lag er verstümmelt und dem Tode nahe. Ein Großer hauchte einmal über seinen Körper und wartete, während der Sand der Zeit seine Wunden heilte. Dann wurde Baristolth gebunden, als {link:the-night-watch}Wächter{/link} zu verweilen, so lange er gebraucht wurde. Seine Wacht hat seither angedauert.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Baristolth ist ein lebendiger Faden zum alten Krieg. Er gab vor tausend Jahren ein Versprechen, und er glaubt, dass die Stunde gekommen ist, es einzulösen. Er spürt das Land rings um die Stöcke beben, und er weiß, dass die {link:qiraji}Qiraji{/link} sich zum Krieg rüsten.]=],
		},
		{
			title = "Taten",
			text = [=[• Er wurde vor dem Tod gerettet und als {link:the-night-watch}Wächter{/link} gebunden.
• Er beobachtet die Stöcke und spürt das Land erzittern, während die {link:qiraji}Qiraji{/link} den Krieg planen.
• Er sendet Botschaft zu den Höhlen der Zeit, um zu erfahren, ob sein Meister zurückgekehrt ist.]=],
		},
		{
			title = "Nicht überliefert",
			text = [=[Keine Aufzeichnung nennt Baristolths Volk oder sein Leben, bevor er gebunden wurde.]=],
		},
	},
	chapters = {
		{
			title = "Was das Morgen bringt",
			hint = "Sucht für den Wächter die Ruhestätte der bronzenen Drachen.",
			text = [=[Baristolth konnte nicht handeln, bevor er eines wusste: ob der Meister, der ihn gerettet hatte, in die Welt zurückgekehrt war. Er sandte einen Boten zu den Höhlen der Zeit in {link:tanaris}Tanaris{/link}, um Anachronos von der Brut {red:nozdormu}Nozdormus{/red} zu finden. Als die Antwort kam, sagte er, dass alles so sei, wie es sein solle. Der Große habe sich erhoben, und seine lange Wacht nähere sich ihrem Ende. Ein zweiter Krieg kam auf die Wüste zu.]=],
		},
	},
	mentions = {
		{ text = "Was das Morgen bringt" },
	},
	bonds = {
		{ id = "anachronos", name = "Anachronos", note = "der Meister, auf den er wartet" },
		{ id = "ralo-shan-the-eternal-watcher", name = "Ralo'shan der Ewige Wächter", note = "ein weiterer, der vom alten Krieg geblieben ist" },
		{ id = "commander-mar-alith", name = "Kommandant Mar'alith", note = "teilt seine Burg mit ihm" },
	},
})

Translate("deDE", "geologist-larksbane", {
	title = "Geologin Larksbane",
	subtitle = "Gelehrte von Burg Cenarius",
	found = "Burg Cenarius",
	hint = "Sprecht mit der Geologin, die dem Summen der Wüste lauscht.",
	allegiance = "Zirkel des Cenarius",
	aliases = { "Larksbane" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Geologin Larksbane erforscht die Steine und Kristalle von {link:silithus}Silithus{/link} für den {link:cenarion-circle}Zirkel des Cenarius{/link}. Sie hört in der Wüste ein Summen, das mit jedem Tag lauter wird, und sie ist sicher, dass die Kristalle der Stöcke die {link:qiraji}Silithiden{/link} in den Wahnsinn treiben. Ihre Arbeit führt sie von den Ruinen eines Lagers des Schattenhammers bis zu den Knochen eines toten Drachen.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Wo Soldaten nur Feinde sehen, die es zu töten gilt, sieht Larksbane Botschaften, die es zu lesen gilt. Sie brach das Schweigen der Glyphenkristalle. Der Schlüssel, den sie suchte, birgt, wie sie glaubt, zwanzigtausend Jahre Geschichte.]=],
		},
		{
			title = "Taten",
			text = [=[• Sie sammelte die zerbrochene Tafel eines zerstörten Kultlagers und sandte sie einem Abtrünnigen, damit er sie lese.
• Sie fand heraus, wie die Glyphenkristalle der Stöcke ihre Botschaften übertragen.
• Sie entwarf die Glyphen, die einen Abgesandten der {link:qiraji}Qiraji{/link} aus seinem Versteck rufen konnten.]=],
		},
	},
	chapters = {
		{
			title = "Das Rätsel des Schattenhammers",
			hint = [=[Sammelt die zerbrochene Tafel aus dem verwüsteten Lager im Nordwesten.]=],
			text = [=[Die Tafel aus dem verwüsteten Lager ergab keinen Sinn. Jedes Wort ließ sich lesen, und doch bedeuteten die Worte zusammen nichts. Larksbane wusste, dass die Sekten des Schattenhammers manchmal in Geheimschrift schreiben. Gerüchte sprachen von einem Kultisten namens {link:hermit-ortell}Ortell{/link}, der seinem Orden entflohen war und als Einsiedler in den Bergen lebte. Wenn jemand sie lesen konnte, dann er.]=],
		},
		{
			title = "Das Glyphenprisma",
			hint = [=[Bringt ihr das Prisma, das die Zwerge aus den Abdrücken der Stöcke gefertigt haben.]=],
			text = [=[Die {link:dwarves}Zwerge{/link} hatten die Glyphen aller drei Stöcke auf ein Kristallprisma übertragen, doch sie konnten nichts lesen. Larksbane erkannte den Grund. Auf der Oberfläche gab es nichts zu lesen. Die äußere Schicht des Prismas musste sich drehen und auf die Zeichen des inneren Kristalls treffen, bevor eine Botschaft hindurchgelangen konnte. Nur ein einziger Hinweis blieb auf seiner Fläche, und er sah düster aus.]=],
		},
		{
			title = "Der Ruf",
			hint = [=[Zeichnet die Glyphen des Rufens an den Knochen von Grakkarond.]=],
			text = [=[Die Glyphen zeigten einen Abgesandten der {link:qiraji}Qiraji{/link}, der sich bei den Knochen eines Drachen mit drei Stockherren traf. Larksbane schrieb den Code ab, der über ihnen stand. In den Sand an den {link:bones-of-grakkarond}Knochen von Grakkarond{/link} gezeichnet, würde er die Oberanführer herbeirufen und hinter ihnen den Abgesandten, der den Schlüssel zu den Kristallen besaß. Als dieser Schlüssel in ihre Hände gelegt wurde, sagte sie, sie halte zwanzigtausend Jahre Geschichte.]=],
		},
	},
	mentions = {
		{ text = "Das Rätsel des Schattenhammers" },
		{ text = "Der Abtrünnige" },
		{ text = "Das Rätsel lösen" },
		{ text = "Der Ruf" },
	},
	bonds = {
		{ id = "hermit-ortell", name = "Einsiedler Ortell", note = "liest den Code des Kults" },
		{ id = "rutgar-glyphshaper", name = "Rutgar Glyphshaper", note = "schrieb die Glyphen ab" },
		{ id = "commander-mar-alith", name = "Kommandant Mar'alith", note = "ihr Kommandant" },
	},
})

Translate("deDE", "hermit-ortell", {
	title = "Einsiedler Ortell",
	subtitle = "Abtrünniger des Schattenhammers",
	found = [=[Ortells Unterschlupf, in den Bergen südlich des Südwindpostens]=],
	hint = [=[Findet den Einsiedler, der sich in den südlichen Bergen vor seinen einstigen Brüdern verbirgt.]=],
	allegiance = "Er selbst · einst der Schattenhammer",
