	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Hochlord Demitrian wartet im Nordwesten von {link:silithus}Silithus{/link} neben einem verwüsteten Feld. Er lehrt, dass die {red:old-gods}Alten Götter{/red} die Welt erschufen und von den Titanen gestürzt wurden, die er Usurpatoren nennt. Er dient Thunderaan, dem Prinzen der Lüfte. In den Kriegen der {link:elements}Elemente{/link}, sagt er, verrieten die Leutnants des Feuerfürsten {red:ragnaros}Ragnaros{/red} Thunderaan, und Ragnaros schlug ihn nieder und nährte sich von seiner Essenz. Das Wenige, das übrig blieb, wurde in einem Talisman gebunden, und der Talisman wurde entzweigebrochen.]=],
